<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {X,RefreshCw,Download,ExternalLink,Plus,Minus} from 'lucide-vue-next';import {download} from '../api';
const emit=defineEmits<{close:[]}>();const apiUrl="https://services.arcgis.com/3vStCH7NDoBOZ5zn/arcgis/rest/services/Sewer_Pipe_Non_Pressure/FeatureServer/1/query?where=1%3D1&geometry=153.415%2C-28.010%2C153.435%2C-27.990&geometryType=esriGeometryEnvelope&inSR=4326&spatialRel=esriSpatialRelIntersects&outFields=OBJECTID%2CSAPOBJECTID%2CDIAMETER_MM%2CLENGTH_M%2CPIPE_NON_PRESSURE_MATERIAL%2CFROM_SAPID%2CTO_SAPID&outSR=4326&returnGeometry=true&resultRecordCount=180&f=geojson";const loading=ref(false),error=ref(''),origin=ref(''),zoom=ref(1),filter=ref(false),basemap=ref(false),failedTiles=ref(false),offset=ref({x:0,y:0}),drag=ref<{x:number;y:number;px:number;py:number}|null>(null);
interface Feature{type:string;geometry:{type:string;coordinates:number[][]};properties:{OBJECTID:number;SAPOBJECTID:string;DIAMETER_MM:number|null;LENGTH_M:number|null;PIPE_NON_PRESSURE_MATERIAL:string;FROM_SAPID:string;TO_SAPID:string}}
const features=ref<Feature[]>([]),selected=ref<Feature|null>(null);const shown=computed(()=>features.value.filter(f=>!filter.value||f.properties.DIAMETER_MM!=null&&f.properties.DIAMETER_MM>=200&&f.properties.DIAMETER_MM<=300));
const project=(c:number[])=>({x:(c[0]+180)/360*256*2**17,y:(1-Math.log(Math.tan(c[1]*Math.PI/180)+1/Math.cos(c[1]*Math.PI/180))/Math.PI)/2*256*2**17});
const bounds=computed(()=>{const pts=features.value.flatMap(f=>f.geometry.coordinates.map(project));if(!pts.length)return{x:0,y:0,w:960,h:600};const x=Math.min(...pts.map(p=>p.x)),y=Math.min(...pts.map(p=>p.y)),w=Math.max(...pts.map(p=>p.x))-x,h=Math.max(...pts.map(p=>p.y))-y;return{x:x-w*.08,y:y-h*.08,w:w*1.16,h:h*1.16};});
const tiles=computed(()=>{if(!basemap.value)return[];const b=bounds.value,z=15,size=1024,x0=Math.floor(b.x/size),y0=Math.floor(b.y/size),x1=Math.floor((b.x+b.w)/size),y1=Math.floor((b.y+b.h)/size),out=[];if((x1-x0+1)*(y1-y0+1)>80)return[];for(let x=x0;x<=x1;x++)for(let y=y0;y<=y1;y++)out.push({url:`https://tile.openstreetmap.org/${z}/${x}/${y}.png`,x:x*size,y:y*size,size});return out;});
const view=computed(()=>{const b=bounds.value;return`${b.x+offset.value.x} ${b.y+offset.value.y} ${b.w/zoom.value} ${b.h/zoom.value}`;});const points=(f:Feature)=>f.geometry.coordinates.map(c=>{const p=project(c);return`${p.x},${p.y}`;}).join(' ');
async function load(){loading.value=true;error.value='';try{const res=await fetch(apiUrl,{signal:AbortSignal.timeout(18000)});if(!res.ok)throw Error('公开服务暂时不可用');const j=await res.json();if(!j.features?.length)throw Error('公开服务未返回管线');features.value=j.features.filter((f:Feature)=>f.geometry?.type==='LineString');origin.value='在线数据 · '+new Date().toLocaleString();}catch{try{const j=await(await fetch('/reference/gold-coast-sewer.geojson')).json();features.value=j.features;origin.value='本地资料快照 · 2026-10-29';error.value='在线查询暂不可用，当前显示已获取的公开数据快照。';}catch{error.value='公开数据暂时无法读取，请稍后重试。';}}finally{loading.value=false;}}
function move(e:MouseEvent){if(!drag.value)return;const w=(e.currentTarget as SVGSVGElement).getBoundingClientRect().width;const r=bounds.value.w/zoom.value/w;offset.value={x:drag.value.px-(e.clientX-drag.value.x)*r,y:drag.value.py-(e.clientY-drag.value.y)*r};}
onMounted(load);
</script><template><Teleport to="body"><div class="public-backdrop"><section class="public-network"><div class="panel-heading"><div><small>PUBLIC UTILITY GIS / 公开管网参考</small><h2>黄金海岸市 · 无压污水管网</h2><p>真实GIS资产资料，保留公开图层的折线坐标与管径。参考区域不属于当前作业片区。</p></div><button @click="emit('close')" aria-label="关闭公开管网"><X :size="24"/></button></div><div class="public-tools"><span>{{shown.length}} / {{features.length}} 条管线 · {{origin||'正在查询公开服务…'}}</span><label class="check-label"><input v-model="filter" type="checkbox"/>仅看200—300mm</label><label class="check-label"><input v-model="basemap" type="checkbox"/>显示地面底图</label><button class="outline" @click="load" :disabled="loading"><RefreshCw :size="16"/>刷新API</button><button class="outline" @click="download('Gold-Coast-Sewer-CC-BY-3.0.geojson',{type:'FeatureCollection',features,source:'City of Gold Coast · CC BY 3.0',license:'https://creativecommons.org/licenses/by/3.0/'})"><Download :size="16"/>导出</button></div><div v-if="error" class="notice">{{error}}</div><div class="public-map-layout"><div class="public-canvas"><svg :viewBox="view" aria-label="黄金海岸真实无压污水管网" @mousedown="e=>drag={x:e.clientX,y:e.clientY,px:offset.x,py:offset.y}" @mousemove="move" @mouseup="drag=null" @mouseleave="drag=null" @wheel.prevent="e=>zoom=Math.max(.5,Math.min(8,zoom*(e.deltaY>0?.9:1.1)))"><rect :x="bounds.x-10000" :y="bounds.y-10000" width="30000" height="30000" fill="#edf3ef"/><image v-for="t in tiles" :key="t.url" :href="t.url" :x="t.x" :y="t.y" :width="t.size" :height="t.size" opacity=".75" @error="failedTiles=true"/><g v-for="f in shown" :key="f.properties.OBJECTID" @mouseenter="selected=f" @click.stop="selected=f"><polyline :points="points(f)" stroke="transparent" stroke-width="12" fill="none" vector-effect="non-scaling-stroke"/><polyline :points="points(f)" :stroke="selected?.properties.OBJECTID===f.properties.OBJECTID?'#ce8a3e':'#238575'" :stroke-width="selected?.properties.OBJECTID===f.properties.OBJECTID?5:2.5" fill="none" vector-effect="non-scaling-stroke"/></g></svg><div class="map-controls"><button @click="zoom*=1.2" title="放大"><Plus :size="18"/></button><button @click="zoom/=1.2" title="缩小"><Minus :size="18"/></button></div><div class="map-attribution" v-if="basemap">© OpenStreetMap contributors{{failedTiles?' · 底图暂不可用':''}}</div></div><aside class="public-info"><h3>管线属性</h3><template v-if="selected"><dl><dt>资产编号</dt><dd>{{selected.properties.SAPOBJECTID}}</dd><dt>管径</dt><dd>{{selected.properties.DIAMETER_MM??'未公开'}} mm</dd><dt>长度</dt><dd>{{selected.properties.LENGTH_M??'未公开'}} m</dd><dt>材质代码</dt><dd>{{selected.properties.PIPE_NON_PRESSURE_MATERIAL||'未公开'}}</dd><dt>上游节点</dt><dd>{{selected.properties.FROM_SAPID||'未公开'}}</dd><dt>下游节点</dt><dd>{{selected.properties.TO_SAPID||'未公开'}}</dd></dl></template><p v-else class="hint">悬停或点击任意管线查看档案</p><hr/><h3>数据来源</h3><p>City of Gold Coast<br>Sewer Pipe Non Pressure<br>CC BY 3.0</p><p>当前查询为局部区域，最多180条，不代表完整城市管网。</p><a :href="apiUrl" target="_blank" rel="noopener" class="text-btn">查看原始API<ExternalLink :size="14"/></a><a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener" class="text-btn">查看数据许可</a><p class="hint">现场巡检仍使用本地授权档案。公开资产图用于功能参考，未经现场核验不作为作业依据。</p></aside></div></section></div></Teleport></template>
